 12354  /************************************************************************
 12355   *                                                                      *
 12356   *              Front ends when parsing an Entity                       *
 12357   *                                                                      *
 12358   ************************************************************************/
 12359
 12360  static xmlNodePtr
 12361  xmlCtxtParseContent(xmlParserCtxtPtr ctxt, xmlParserInputPtr input,
 12362                      int hasTextDecl) {
 12363      xmlParserInputPtr oldInput;
 12364      xmlNodePtr oldNode, root = NULL;
 12365      int oldNameNr, oldSpaceNr, oldNodeNr;
 12366      int oldWellFormed;
 12367      int oldProgressive;
 12368      int oldNodeLen, oldNodeMem;
 12369
 12370      if (((ctxt->depth > 40) && ((ctxt->options & XML_PARSE_HUGE) == 0)) ||
 12371          (ctxt->depth > 100)) {
 12372          xmlFatalErrMsg(ctxt, XML_ERR_ENTITY_LOOP,
 12373                         "Maximum entity nesting depth exceeded");
 12374          return(NULL);
 12375      }
 12376
 12377      oldNode = ctxt->node;
 12378      oldInput = ctxt->input;
 12379      oldWellFormed = ctxt->wellFormed;
 12380      oldProgressive = ctxt->progressive;
 12381      oldNodeLen = ctxt->nodelen;
 12382      oldNodeMem = ctxt->nodemem;
 12383
 12384      oldNameNr = ctxt->nameNr;
 12385      oldSpaceNr = ctxt->spaceNr;
 12386      oldNodeNr = ctxt->nodeNr;
 12387
 12388      root = xmlNewDocNode(ctxt->myDoc, NULL, BAD_CAST "pseudoroot", NULL);
 12389      if (root == NULL) {
 12390          xmlErrMemory(ctxt);
 12391          return(NULL);
 12392      }
 12393
 12394      /*
 12395       * TODO: It would be nice if we could simply push the input onto
 12396       * the input stack. But there's still some code that assumes that
 12397       * ctxt->inputNr > 1 means that we're inside a parameter entity.
 12398       */
 12399      ctxt->input = input;
 12400      ctxt->progressive = 0;
 12401      ctxt->nodelen = 0;
 12402      ctxt->nodemem = 0;
 12403
 12404      nameNsPush(ctxt, root->name, NULL, NULL, 0, 0);
 12405      spacePush(ctxt, -1);
 12406      nodePush(ctxt, root);
 12407
 12408      if (hasTextDecl) {
 12409          xmlDetectEncoding(ctxt);
 12410
 12411          /*
 12412           * Parse a possible text declaration first
 12413           */
 12414          if ((CMP5(CUR_PTR, '<', '?', 'x', 'm', 'l')) &&
 12415              (IS_BLANK_CH(NXT(5)))) {
 12416              xmlParseTextDecl(ctxt);
 12417              /*
 12418               * An XML-1.0 document can't reference an entity not XML-1.0
 12419               */
 12420              if ((xmlStrEqual(ctxt->version, BAD_CAST "1.0")) &&
 12421                  (!xmlStrEqual(ctxt->input->version, BAD_CAST "1.0"))) {
 12422                  xmlFatalErrMsg(ctxt, XML_ERR_VERSION_MISMATCH,
 12423                                 "Version mismatch between document and "
 12424                                 "entity\n");
 12425              }
 12426          }
 12427      }
 12428
 12429      ctxt->depth++;
 12430      xmlParseContent(ctxt);
 12431      ctxt->depth--;
 12432
 12433      if ((RAW == '<') && (NXT(1) == '/')) {
 12434          xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
 12435      } else if (RAW != 0) {
 12436          xmlFatalErr(ctxt, XML_ERR_EXTRA_CONTENT, NULL);
 12437      }
 12438
 12439      if ((ctxt->wellFormed == 0) &&
 12440          ((ctxt->recovery == 0) || (ctxt->errNo == XML_ERR_NO_MEMORY))) {
 12441          xmlFreeNode(root);
 12442          root = NULL;
 12443      }
 12444
 12445      /*
 12446       * If the entity wasn't balanced, we have to pop items from
 12447       * several stacks.
 12448       */
 12449      while (ctxt->nameNr > oldNameNr) {
 12450          xmlStartTag *tag = &ctxt->pushTab[ctxt->nameNr - 1];
 12451
 12452          if (tag->nsNr != 0)
 12453              xmlParserNsPop(ctxt, tag->nsNr);
 12454
 12455          namePop(ctxt);
 12456      }
 12457
 12458      while (ctxt->spaceNr > oldSpaceNr) {
 12459          spacePop(ctxt);
 12460      }
 12461
 12462      while (ctxt->nodeNr > oldNodeNr) {
 12463          nodePop(ctxt);
 12464      }
 12465
 12466      ctxt->node = oldNode;
 12467      ctxt->input = oldInput;
 12468      ctxt->wellFormed = oldWellFormed && ctxt->wellFormed;
 12469      ctxt->progressive = oldProgressive;
 12470      ctxt->nodelen = oldNodeLen;
 12471      ctxt->nodemem = oldNodeMem;
 12472
 12473      return(root);
 12474  }
