 12476  /**
 12477   * xmlParseCtxtExternalEntity:
 12478   * @ctx:  the existing parsing context
 12479   * @URL:  the URL for the entity to load
 12480   * @ID:  the System ID for the entity to load
 12481   * @lst:  the return value for the set of parsed nodes
 12482   *
 12483   * Parse an external general entity within an existing parsing context
 12484   * An external general parsed entity is well-formed if it matches the
 12485   * production labeled extParsedEnt.
 12486   *
 12487   * [78] extParsedEnt ::= TextDecl? content
 12488   *
 12489   * Returns 0 if the entity is well formed, -1 in case of args problem and
 12490   *    the parser error code otherwise
 12491   */
 12492
 12493  int
 12494  xmlParseCtxtExternalEntity(xmlParserCtxtPtr ctxt, const xmlChar *URL,
 12495                             const xmlChar *ID, xmlNodePtr *list) {
 12496      xmlParserInputPtr input;
 12497      xmlNodePtr root;
 12498      unsigned long consumed;
 12499
 12500      if (list != NULL)
 12501          *list = NULL;
 12502
 12503      if (ctxt == NULL)
 12504          return(XML_ERR_ARGUMENT);
 12505
 12506      input = xmlLoadExternalEntity((char *)URL, (char *)ID, ctxt);
 12507      if (input == NULL)
 12508          return(ctxt->errNo);
 12509
 12510      root = xmlCtxtParseContent(ctxt, input, 1 /* hasTextDecl */);
 12511
 12512      if ((list != NULL) && (root != NULL)) {
 12513          xmlNodePtr cur;
 12514
 12515          /*
 12516           * Return the newly created nodeset after unlinking it from
 12517           * their pseudo parent.
 12518           */
 12519          cur = root->children;
 12520          *list = cur;
 12521          while (cur != NULL) {
 12522              cur->parent = NULL;
 12523              cur = cur->next;
 12524          }
 12525          root->children = NULL;
 12526          root->last = NULL;
 12527      }
 12528
 12529      /*
 12530       * Also record the size of the entity parsed
 12531       */
 12532      consumed = input->consumed;
 12533      xmlSaturatedAddSizeT(&consumed, input->cur - input->base);
 12534
 12535      xmlSaturatedAdd(&ctxt->sizeentities, consumed);
 12536      xmlSaturatedAdd(&ctxt->sizeentcopy, consumed);
 12537
 12538      xmlFreeNode(root);
 12539      xmlFreeInputStream(input);
 12540
 12541      return(ctxt->errNo);
 12542  }
